pub struct MacAxBackend { tx: Sender<Command> }

impl MacAxBackend {
    pub fn new(pid: i32, title: impl Into<String>) -> Result<Self, String> {
        let title=title.into();let(tx,rx)=mpsc::channel();
        thread::Builder::new().name("desktop-cli-ax".into()).spawn(move||worker_main(pid,title,rx)).map_err(|e|format!("failed to spawn AX actor: {e}"))?;
        let backend=Self{tx};backend.call(|reply|Command::Ping{reply})?;Ok(backend)
    }
    fn call<T:Send+'static>(&self,make:impl FnOnce(Sender<Result<T,String>>)->Command)->Result<T,String>{let(tx,rx)=mpsc::channel();self.tx.send(make(tx)).map_err(|_|"AX actor disconnected".to_string())?;rx.recv().map_err(|_|"AX actor disconnected".to_string())?}
}

impl AccessibilityBackend for MacAxBackend {
    fn kind(&self)->BackendKind{BackendKind::MacAx}
    fn roots(&mut self)->Result<Vec<BackendRoot>,String>{self.call(|reply|Command::Roots{reply})}
    fn inspect(&mut self,identity:&NativeIdentity,mask:InspectMask)->Result<ElementSnapshot,String>{let identity=identity.clone();self.call(|reply|Command::Inspect{identity,mask,reply})}
    fn children(&mut self,identity:&NativeIdentity,range:ChildRange)->Result<Vec<NativeIdentity>,String>{let identity=identity.clone();self.call(|reply|Command::Children{identity,range,reply})}
    fn perform(&mut self,identity:&NativeIdentity,request:ActionRequest)->Result<BackendActionResult,String>{let identity=identity.clone();self.call(|reply|Command::Perform{identity,request,reply})}
    fn query_text(&mut self,identity:&NativeIdentity,query:TextQuery)->Result<TextResult,String>{let identity=identity.clone();self.call(|reply|Command::Text{identity,query,reply})}
    fn plan_query(&self,selector:&Selector)->NativeQueryPlan{let mut pushed=Vec::new();let mut residual=Vec::new();for step in &selector.steps{for test in &step.tests{match test{SelectorTest::Role(r)=>pushed.push(format!("AXRole={}",r.as_str())),SelectorTest::StableId(id)=>pushed.push(format!("AXIdentifier={id}")),SelectorTest::Property(p) if matches!(p.name.as_str(),"name"|"value"|"native.subrole")=>pushed.push(format!("{} {:?} {}",p.name,p.op,p.value)),SelectorTest::State(p) if matches!(p.state,State::Enabled|State::Focused|State::Selected|State::Expanded)=>pushed.push(format!("state.{:?}={:?}",p.state,p.expected)),other=>residual.push(format!("{:?}",other))}}}NativeQueryPlan{backend:BackendKind::MacAx,description:"AX has no general server-side selector engine; simple role/id/state predicates are used for early-prune traversal and bulk attribute reads, with residual predicates evaluated semantically".into(),pushed_predicates:pushed,residual_selector:if residual.is_empty(){String::new()}else{selector.source.clone()},exact:false}}
}

enum Command{Ping{reply:Sender<Result<(),String>>},Roots{reply:Sender<Result<Vec<BackendRoot>,String>>},Inspect{identity:NativeIdentity,mask:InspectMask,reply:Sender<Result<ElementSnapshot,String>>},Children{identity:NativeIdentity,range:ChildRange,reply:Sender<Result<Vec<NativeIdentity>,String>>},Perform{identity:NativeIdentity,request:ActionRequest,reply:Sender<Result<BackendActionResult,String>>},Text{identity:NativeIdentity,query:TextQuery,reply:Sender<Result<TextResult,String>>}}

struct Worker{pid:i32,root:u64,elements:HashMap<u64,AXUIElementRef>}
unsafe impl Send for Worker{}

impl Drop for Worker{fn drop(&mut self){for(_,element)in self.elements.drain(){unsafe{CFRelease(element as CFTypeRef);}}}}

fn worker_main(pid:i32,title:String,rx:Receiver<Command>){let mut state=Worker::new(pid,&title);while let Ok(command)=rx.recv(){match command{Command::Ping{reply}=>{let _=reply.send(state.as_ref().map(|_|()).map_err(Clone::clone));},Command::Roots{reply}=>{let _=reply.send(state.as_mut().map_err(|e|(*e).clone()).and_then(Worker::roots));},Command::Inspect{identity,mask,reply}=>{let _=reply.send(state.as_mut().map_err(|e|(*e).clone()).and_then(|s|s.inspect(&identity,mask)));},Command::Children{identity,range,reply}=>{let _=reply.send(state.as_mut().map_err(|e|(*e).clone()).and_then(|s|s.children(&identity,range)));},Command::Perform{identity,request,reply}=>{let _=reply.send(state.as_mut().map_err(|e|(*e).clone()).and_then(|s|s.perform(&identity,request)));},Command::Text{identity,query,reply}=>{let _=reply.send(state.as_mut().map_err(|e|(*e).clone()).and_then(|s|s.text(&identity,query)));}}}}

impl Worker{
    fn new(pid:i32,title:&str)->Result<Self,String>{unsafe{let app=AXUIElementCreateApplication(pid);if app.is_null(){return Err("AXUIElementCreateApplication returned null".into());}let _=AXUIElementSetMessagingTimeout(app,2.0);let mut worker=Self{pid,root:0,elements:HashMap::new()};let app_token=worker.retain_owned(app);let mut chosen=app_token;if let Ok(windows)=copy_element_array(app,kAXWindowsAttribute){let needle=title.to_ascii_lowercase();for window in windows{let token=worker.retain_borrowed(window);let name=copy_string(window,kAXTitleAttribute).unwrap_or_default();if !needle.is_empty()&&(name.eq_ignore_ascii_case(title)||name.to_ascii_lowercase().contains(&needle)){chosen=token;break;}}}worker.root=chosen;Ok(worker)}}
    fn retain_owned(&mut self,element:AXUIElementRef)->u64{let token=element as usize as u64;if self.elements.contains_key(&token){unsafe{CFRelease(element as CFTypeRef);}}else{self.elements.insert(token,element);}token}
    fn retain_borrowed(&mut self,element:AXUIElementRef)->u64{let token=element as usize as u64;if !self.elements.contains_key(&token){unsafe{CFRetain(element as CFTypeRef);};self.elements.insert(token,element);}token}
    fn element(&self,identity:&NativeIdentity)->Result<AXUIElementRef,String>{let token=match identity{NativeIdentity::Ax{registry_token,pid} if *pid==self.pid=>*registry_token,_=>return Err("expected AX identity for this process".into())};self.elements.get(&token).copied().ok_or_else(||"AX element reference is stale; refresh the session".into())}
    fn identity(&self,token:u64)->NativeIdentity{NativeIdentity::Ax{registry_token:token,pid:self.pid}}
    fn roots(&mut self)->Result<Vec<BackendRoot>,String>{let e=*self.elements.get(&self.root).ok_or_else(||"AX root is unavailable".to_string())?;Ok(vec![BackendRoot{native:self.identity(self.root),name:unsafe{copy_string(e,kAXTitleAttribute).ok()}.filter(|s|!s.is_empty()),pid:Some(self.pid as u32)}])}
    fn inspect(&mut self,identity:&NativeIdentity,_mask:InspectMask)->Result<ElementSnapshot,String>{unsafe{let e=self.element(identity)?;let role_native=copy_string(e,kAXRoleAttribute).unwrap_or_else(|_|"AXUnknown".into());let subrole=copy_string(e,kAXSubroleAttribute).ok().filter(|s|!s.is_empty());let role=role_from_ax(&role_native,subrole.as_deref());let name=copy_string(e,kAXTitleAttribute).ok().filter(|s|!s.is_empty()).or_else(||copy_string(e,kAXDescriptionAttribute).ok().filter(|s|!s.is_empty()));let description=copy_string(e,kAXHelpAttribute).ok().filter(|s|!s.is_empty());let stable_id=copy_string(e,kAXIdentifierAttribute).ok().filter(|s|!s.is_empty());let mut states=StateSet::default();for(attr,state)in[(kAXEnabledAttribute,State::Enabled),(kAXFocusedAttribute,State::Focused),(kAXSelectedAttribute,State::Selected),(kAXExpandedAttribute,State::Expanded),(kAXRequiredAttribute,State::Required)]{if let Ok(v)=copy_bool(e,attr){states.set_bool(state,v);}}if role==Role::PasswordInput{states.set_bool(State::Protected,true);}let value=copy_typed(e,kAXValueAttribute).ok().and_then(|v|match v{PropertyValue::Ref(_)|PropertyValue::Refs(_)=>None,other=>Some(other)});let mut capabilities=BTreeSet::new();let actions_native=copy_action_names(e).unwrap_or_default();let mut actions=Vec::new();for action in &actions_native{if let Some(semantic)=semantic_action_from_ax(action){actions.push(ElementAction{semantic:Some(semantic),native:NativeAction{backend:BackendKind::MacAx,name:action.clone(),index:None},name:action.clone(),description:None,key_binding:None});}}if !actions.is_empty(){capabilities.insert(CapabilityKind::Action);}let mut settable=false;let attr=CFString::new(kAXValueAttribute);if AXUIElementIsAttributeSettable(e,attr.as_concrete_TypeRef(),&mut settable)==0&&settable{capabilities.insert(CapabilityKind::Value);states.set_bool(State::Editable,true);}if matches!(role,Role::TextInput|Role::SearchInput|Role::PasswordInput|Role::Text|Role::StaticText){capabilities.insert(CapabilityKind::Text);if settable{capabilities.insert(CapabilityKind::EditableText);}}if role==Role::Table{capabilities.insert(CapabilityKind::Table);}if role==Role::Cell{capabilities.insert(CapabilityKind::TableCell);}capabilities.insert(CapabilityKind::Component);let geometry=match(copy_point(e,kAXPositionAttribute),copy_size(e,kAXSizeAttribute)){(Ok(p),Ok(s))=>Some(Geometry{bounds:Rect{x:p.x,y:p.y,width:s.width,height:s.height},coordinate_space:CoordinateSpace::ScreenLogical,visibility:Visibility::Unknown,z_order:None}),_=>None};let mut properties=BTreeMap::new();if let Some(s)=subrole.clone(){properties.insert("native.subrole".into(),PropertyValue::String(s));}for attr in [kAXRoleDescriptionAttribute,kAXValueDescriptionAttribute,kAXOrientationAttribute,kAXURLAttribute]{if let Ok(v)=copy_typed(e,attr){properties.insert(format!("native.{attr}"),v);}}Ok(ElementSnapshot{node:0,identity:ElementIdentity{native:identity.clone(),stable_id},role,native_role:NativeRole{backend:BackendKind::MacAx,role:role_native,subrole,numeric_id:None},name,description,value,states,capabilities,actions:actions.clone(),geometry,parent:None,children:Vec::new(),relations:Vec::new(),properties:properties.clone(),native:NativeMetadata{attributes:properties,interfaces:BTreeSet::new(),actions:actions_native}})}}
    fn children(&mut self,identity:&NativeIdentity,range:ChildRange)->Result<Vec<NativeIdentity>,String>{unsafe{let e=self.element(identity)?;let children=copy_element_array(e,kAXChildrenAttribute)?;let start=range.offset.min(children.len());let end=(start+range.limit).min(children.len());let mut out=Vec::new();for child in children[start..end].iter().copied(){let token=self.retain_borrowed(child);out.push(self.identity(token));}Ok(out)}}
    fn perform(&mut self,identity:&NativeIdentity,request:ActionRequest)->Result<BackendActionResult,String>{unsafe{let e=self.element(identity)?;if matches!(request.action,SemanticAction::SetValue|SemanticAction::SetText|SemanticAction::ReplaceText){let value=match request.value{ActionValue::Text(v)=>{let s=CFString::new(&v);let rc=AXUIElementSetAttributeValue(e,CFString::new(kAXValueAttribute).as_concrete_TypeRef(),s.as_CFTypeRef());return Ok(BackendActionResult{success:rc==0,native_action:Some("AXValue=set".into()),message:(rc!=0).then(||format!("AX error {rc}"))});},ActionValue::Number(v)=>{let n=CFNumber::from_f64(v);let rc=AXUIElementSetAttributeValue(e,CFString::new(kAXValueAttribute).as_concrete_TypeRef(),n.as_CFTypeRef());return Ok(BackendActionResult{success:rc==0,native_action:Some("AXValue=set".into()),message:(rc!=0).then(||format!("AX error {rc}"))});},_=>return Err("AX value action requires text or number".into())};let _=value;}if request.action==SemanticAction::Focus{let yes=core_foundation::boolean::CFBoolean::true_value();let rc=AXUIElementSetAttributeValue(e,CFString::new(kAXFocusedAttribute).as_concrete_TypeRef(),yes.as_CFTypeRef());return Ok(BackendActionResult{success:rc==0,native_action:Some("AXFocused=set".into()),message:(rc!=0).then(||format!("AX error {rc}"))});}let native=request.native_hint.as_ref().map(|n|n.name.clone()).or_else(||default_ax_action(request.action)).ok_or_else(||format!("no AX action for {:?}",request.action))?;let rc=AXUIElementPerformAction(e,CFString::new(&native).as_concrete_TypeRef());Ok(BackendActionResult{success:rc==0,native_action:Some(native),message:(rc!=0).then(||format!("AX error {rc}"))})}}
    fn text(&mut self,identity:&NativeIdentity,query:TextQuery)->Result<TextResult,String>{unsafe{let e=self.element(identity)?;let text=copy_string(e,kAXValueAttribute).or_else(|_|copy_string(e,kAXTitleAttribute))?;match query{TextQuery::All=>Ok(TextResult::Text(text)),TextQuery::Range(r)=>Ok(TextResult::Text(text.chars().skip(r.start).take(r.end.saturating_sub(r.start)).collect())),TextQuery::Character(i)=>Ok(TextResult::Text(text.chars().nth(i).map(|c|c.to_string()).unwrap_or_default())),TextQuery::Line(line)=>Ok(TextResult::Text(text.lines().nth(line).unwrap_or("").into())),TextQuery::Bounds(range)=>{let cf_range=core_foundation_sys::base::CFRange{location:range.start as isize,length:range.end.saturating_sub(range.start) as isize};let ax=AXValueCreate(kAXValueTypeCFRange,&cf_range as *const _ as *const c_void);if ax.is_null(){return Err("failed to create AX range".into());}let mut raw:CFTypeRef=std::ptr::null();let rc=AXUIElementCopyParameterizedAttributeValue(e,CFString::new(kAXBoundsForRangeParameterizedAttribute).as_concrete_TypeRef(),ax as CFTypeRef,&mut raw);CFRelease(ax as CFTypeRef);if rc!=0||raw.is_null(){return Err(format!("AX bounds-for-range error {rc}"));}let v=decode_cf(raw);CFRelease(raw);match v{PropertyValue::Rect(r)=>Ok(TextResult::Bounds(vec![r])),_=>Err("AX bounds-for-range returned unexpected type".into())}},TextQuery::Attributes(_)=>Err("AX attributed-string decoding is not exposed yet".into())}}}
}

unsafe fn copy_raw(element:AXUIElementRef,attribute:&str)->Result<CFTypeRef,String>{let mut raw:CFTypeRef=std::ptr::null();let rc=AXUIElementCopyAttributeValue(element,CFString::new(attribute).as_concrete_TypeRef(),&mut raw);if rc!=0||raw.is_null(){Err(format!("AX attribute {attribute} error {rc}"))}else{Ok(raw)}}
unsafe fn copy_string(element:AXUIElementRef,attribute:&str)->Result<String,String>{let raw=copy_raw(element,attribute)?;let result=if CFGetTypeID(raw)==CFStringGetTypeID(){Ok(CFString::wrap_under_get_rule(raw as _).to_string())}else{Err(format!("AX attribute {attribute} is not a string"))};CFRelease(raw);result}
unsafe fn copy_bool(element:AXUIElementRef,attribute:&str)->Result<bool,String>{let raw=copy_raw(element,attribute)?;let result=if CFGetTypeID(raw)==CFBooleanGetTypeID(){Ok(CFBooleanGetValue(raw as _)!=0)}else{Err(format!("AX attribute {attribute} is not boolean"))};CFRelease(raw);result}
unsafe fn copy_point(element:AXUIElementRef,attribute:&str)->Result<Point,String>{match copy_typed(element,attribute)?{PropertyValue::Point(v)=>Ok(v),_=>Err("AX point attribute has wrong type".into())}}
unsafe fn copy_size(element:AXUIElementRef,attribute:&str)->Result<Size,String>{match copy_typed(element,attribute)?{PropertyValue::Size(v)=>Ok(v),_=>Err("AX size attribute has wrong type".into())}}
unsafe fn copy_typed(element:AXUIElementRef,attribute:&str)->Result<PropertyValue,String>{let raw=copy_raw(element,attribute)?;let value=decode_cf(raw);CFRelease(raw);Ok(value)}
unsafe fn decode_cf(raw:CFTypeRef)->PropertyValue{let tid=CFGetTypeID(raw);if tid==CFStringGetTypeID(){return PropertyValue::String(CFString::wrap_under_get_rule(raw as _).to_string());}if tid==CFBooleanGetTypeID(){return PropertyValue::Bool(CFBooleanGetValue(raw as _)!=0);}if tid==CFNumberGetTypeID(){return CFNumber::wrap_under_get_rule(raw as _).to_f64().map(PropertyValue::F64).unwrap_or(PropertyValue::Opaque{type_name:"CFNumber".into(),debug:None});}if tid==AXValueGetTypeID(){let ax=raw as AXValueRef;match AXValueGetType(ax){kAXValueTypeCGPoint=>{let mut v=CGPoint::new(0.0,0.0);if AXValueGetValue(ax,kAXValueTypeCGPoint,&mut v as *mut _ as *mut c_void){return PropertyValue::Point(Point{x:v.x,y:v.y});}},kAXValueTypeCGSize=>{let mut v=CGSize::new(0.0,0.0);if AXValueGetValue(ax,kAXValueTypeCGSize,&mut v as *mut _ as *mut c_void){return PropertyValue::Size(Size{width:v.width,height:v.height});}},kAXValueTypeCGRect=>{let mut v=CGRect::new(&CGPoint::new(0.0,0.0),&CGSize::new(0.0,0.0));if AXValueGetValue(ax,kAXValueTypeCGRect,&mut v as *mut _ as *mut c_void){return PropertyValue::Rect(Rect{x:v.origin.x,y:v.origin.y,width:v.size.width,height:v.size.height});}},kAXValueTypeCFRange=>{let mut v=core_foundation_sys::base::CFRange{location:0,length:0};if AXValueGetValue(ax,kAXValueTypeCFRange,&mut v as *mut _ as *mut c_void){return PropertyValue::Range(TextRange{start:v.location.max(0) as usize,end:(v.location+v.length).max(0) as usize});}},_=>{}}return PropertyValue::Opaque{type_name:"AXValue".into(),debug:None};}if tid==CFArrayGetTypeID(){return PropertyValue::Opaque{type_name:"CFArray".into(),debug:None};}if tid==AXUIElementGetTypeID(){return PropertyValue::Opaque{type_name:"AXUIElement".into(),debug:None};}PropertyValue::Opaque{type_name:format!("CFTypeID:{tid}"),debug:None}}
unsafe fn copy_element_array(element:AXUIElementRef,attribute:&str)->Result<Vec<AXUIElementRef>,String>{let raw=copy_raw(element,attribute)?;if CFGetTypeID(raw)!=CFArrayGetTypeID(){CFRelease(raw);return Err(format!("AX attribute {attribute} is not an array"));}let array=raw as core_foundation_sys::array::CFArrayRef;let mut out=Vec::new();for i in 0..CFArrayGetCount(array){let child=CFArrayGetValueAtIndex(array,i) as AXUIElementRef;if !child.is_null()&&CFGetTypeID(child as CFTypeRef)==AXUIElementGetTypeID(){out.push(child);}}CFRelease(raw);Ok(out)}
unsafe fn copy_action_names(element:AXUIElementRef)->Result<Vec<String>,String>{let mut raw:core_foundation_sys::array::CFArrayRef=std::ptr::null();let rc=AXUIElementCopyActionNames(element,&mut raw);if rc!=0||raw.is_null(){return Err(format!("AX action names error {rc}"));}let mut out=Vec::new();for i in 0..CFArrayGetCount(raw){let value=CFArrayGetValueAtIndex(raw,i) as CFTypeRef;if !value.is_null()&&CFGetTypeID(value)==CFStringGetTypeID(){out.push(CFString::wrap_under_get_rule(value as _).to_string());}}CFRelease(raw as CFTypeRef);Ok(out)}
fn default_ax_action(action:SemanticAction)->Option<String>{Some(match action{SemanticAction::Activate=>kAXPressAction,SemanticAction::Increment=>kAXIncrementAction,SemanticAction::Decrement=>kAXDecrementAction,SemanticAction::Confirm=>kAXConfirmAction,SemanticAction::Cancel=>kAXCancelAction,SemanticAction::ShowMenu=>kAXShowMenuAction,SemanticAction::RaiseWindow=>kAXRaiseAction,SemanticAction::Select=>kAXPressAction,SemanticAction::Expand=>kAXPressAction,SemanticAction::Collapse=>kAXPressAction,SemanticAction::ScrollIntoView=>return None,SemanticAction::Focus|SemanticAction::SetValue|SemanticAction::SetText|SemanticAction::ReplaceText|SemanticAction::Toggle=>return None}.to_string())}
